begin;

do $$
begin
  if (select count(*) from public.exercises) <> 140 then
    raise exception 'Expected 140 existing exercises before global catalogue conversion';
  end if;

  if (select count(*) from public.exercises) <> (select count(distinct name) from public.exercises) then
    raise exception 'Exercise names must be globally unique before conversion';
  end if;

  if (select count(distinct owner_id) from public.exercises) <> 1 then
    raise exception 'Expected the existing catalogue to have exactly one owner before conversion';
  end if;

  if exists (
    select 1
    from public.session_exercises se
    left join public.exercises e
      on e.id = se.exercise_id
     and e.owner_id = se.owner_id
    where e.id is null
  ) then
    raise exception 'A performed exercise is not linked to its owner-scoped catalogue row';
  end if;
end
$$;

create temporary table movement_matrix_import (
  payload jsonb not null
) on commit drop;

insert into movement_matrix_import (payload)
values (
  convert_from(
    decode($matrix_payload$$matrix_payload$, 'base64'),
    'utf8'
  )::jsonb
);

do $$
declare
  matrix jsonb := (select payload from movement_matrix_import);
begin
  if jsonb_array_length(matrix -> 'exercises') <> 140 then
    raise exception 'Matrix payload must contain 140 exercises';
  end if;

  if jsonb_array_length(matrix -> 'patterns') <> 40 then
    raise exception 'Matrix payload must contain 40 movement patterns';
  end if;

  if exists (
    select name
    from (
      select exercise ->> 'name' as name
      from jsonb_array_elements(matrix -> 'exercises') exercise
      union all
      select name from public.exercises
    ) names
    group by name
    having count(*) <> 2
  ) then
    raise exception 'Matrix exercises do not exactly match the database catalogue';
  end if;
end
$$;

drop policy "Users can view their own exercises" on public.exercises;
drop policy "Users can create their own exercises" on public.exercises;
drop policy "Users can update their own exercises" on public.exercises;
drop policy "Users can delete their own exercises" on public.exercises;

alter table public.session_exercises
  drop constraint session_exercises_exercise_id_owner_id_fkey;

alter table public.exercises
  drop constraint exercises_canonical_exercise_id_owner_id_fkey,
  drop constraint exercises_check,
  drop constraint exercises_id_owner_id_key,
  drop constraint exercises_owner_id_fkey,
  drop constraint exercises_owner_id_name_key;

drop index public.exercises_owner_created_idx;
drop index public.exercises_canonical_owner_idx;
drop index public.session_exercises_exercise_owner_idx;

alter table public.exercises
  add column code text,
  add column description text,
  add column is_active boolean not null default true;

update public.exercises
set code = 'exercise_' || id::text;

alter table public.exercises
  alter column code set not null,
  drop column canonical_exercise_id,
  drop column owner_id,
  add constraint exercises_code_key unique (code),
  add constraint exercises_name_key unique (name),
  add constraint exercises_code_check check (code ~ '^[a-z0-9_]+$'),
  add constraint exercises_name_normalized_check check (
    name <> ''
    and name = regexp_replace(btrim(name), '\s+', ' ', 'g')
  );

alter table public.session_exercises
  add constraint session_exercises_exercise_id_fkey
  foreign key (exercise_id)
  references public.exercises(id)
  on delete restrict;

create index session_exercises_exercise_id_idx
  on public.session_exercises (exercise_id);

create table public.exercise_aliases (
  id bigint generated always as identity primary key,
  exercise_id bigint not null references public.exercises(id) on delete cascade,
  alias text not null check (btrim(alias) <> ''),
  normalized_alias text generated always as (
    lower(regexp_replace(btrim(alias), '\s+', ' ', 'g'))
  ) stored,
  created_at timestamptz not null default now(),
  unique (normalized_alias)
);

create index exercise_aliases_exercise_id_idx
  on public.exercise_aliases (exercise_id);

insert into public.exercise_aliases (exercise_id, alias)
select id, name
from public.exercises;

create table public.movement_patterns (
  id bigint generated always as identity primary key,
  source_order smallint not null unique check (source_order > 0),
  code text not null unique check (code ~ '^[a-z0-9_]+$'),
  name text not null unique check (btrim(name) <> ''),
  plane text not null check (plane in ('sagittal', 'frontal', 'transverse', 'scapular')),
  articulation text not null check (articulation ~ '^[a-z0-9_]+$'),
  action text not null check (btrim(action) <> ''),
  contraction_type text not null check (contraction_type in ('dynamic', 'isometric')),
  description text not null check (btrim(description) <> ''),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

insert into public.movement_patterns (
  source_order,
  code,
  name,
  plane,
  articulation,
  action,
  contraction_type,
  description
)
select
  (pattern ->> 'source_order')::smallint,
  pattern ->> 'code',
  pattern ->> 'name',
  pattern ->> 'plane',
  pattern ->> 'articulation',
  pattern ->> 'action',
  pattern ->> 'contraction_type',
  pattern ->> 'description'
from movement_matrix_import,
     jsonb_array_elements(payload -> 'patterns') pattern;

create table public.movement_mapping_versions (
  id bigint generated always as identity primary key,
  code text not null unique check (code ~ '^[a-z0-9_]+$'),
  name text not null check (btrim(name) <> ''),
  status text not null check (status in ('draft', 'published', 'retired')),
  is_current boolean not null default false,
  methodology_revision text not null check (btrim(methodology_revision) <> ''),
  source_file_name text not null check (btrim(source_file_name) <> ''),
  source_sha256 text not null check (source_sha256 ~ '^[0-9a-f]{64}$'),
  payload_sha256 text not null check (payload_sha256 ~ '^[0-9a-f]{64}$'),
  exercise_count integer not null check (exercise_count > 0),
  pattern_count integer not null check (pattern_count > 0),
  cell_count integer not null check (cell_count = exercise_count * pattern_count),
  nonzero_cell_count integer not null check (
    nonzero_cell_count >= 0 and nonzero_cell_count <= cell_count
  ),
  change_notes text not null check (btrim(change_notes) <> ''),
  created_at timestamptz not null default now(),
  published_at timestamptz,
  check (not is_current or status = 'published'),
  check (
    (status = 'draft' and published_at is null)
    or (status in ('published', 'retired') and published_at is not null)
  )
);

create unique index movement_mapping_versions_one_current_idx
  on public.movement_mapping_versions (is_current)
  where is_current;

insert into public.movement_mapping_versions (
  code,
  name,
  status,
  is_current,
  methodology_revision,
  source_file_name,
  source_sha256,
  payload_sha256,
  exercise_count,
  pattern_count,
  cell_count,
  nonzero_cell_count,
  change_notes,
  published_at
)
values (
  'initial_2026_08_07',
  'Initial 140 by 40 movement-pattern matrix',
  'published',
  true,
  'docs/MOVEMENT_PATTERN_COEFFICIENTS.md@2026-08-07',
  'Movement Pattern Mapping Matrix - Mapping_Matrix.csv',
  '8bc0f6246b0939db59c668de7a95962c2b7a82d3f9445adbef4860177d2241b1',
  '01dc8219500127aa1b78498bddbbb44d0d3c1f92b6e3de769b5fa14c8283a801',
  140,
  40,
  5600,
  556,
  'Initial import of the reviewed matrix. Zero-valued cells are stored explicitly. Individual exercise-pattern rationales remain methodology-level until reviewed.',
  now()
);

create table public.exercise_movement_pattern_coefficients (
  mapping_version_id bigint not null
    references public.movement_mapping_versions(id) on delete restrict,
  exercise_id bigint not null
    references public.exercises(id) on delete restrict,
  movement_pattern_id bigint not null
    references public.movement_patterns(id) on delete restrict,
  coefficient numeric(4, 3) not null check (coefficient between 0 and 1),
  rationale_status text not null default 'methodology_only'
    check (rationale_status in ('methodology_only', 'documented')),
  rationale text not null check (btrim(rationale) <> ''),
  created_at timestamptz not null default now(),
  primary key (mapping_version_id, exercise_id, movement_pattern_id)
);

create index exercise_movement_coefficients_exercise_idx
  on public.exercise_movement_pattern_coefficients (exercise_id, mapping_version_id);
create index exercise_movement_coefficients_pattern_idx
  on public.exercise_movement_pattern_coefficients (
    movement_pattern_id,
    mapping_version_id,
    exercise_id
  );
create index exercise_movement_coefficients_nonzero_idx
  on public.exercise_movement_pattern_coefficients (
    mapping_version_id,
    exercise_id,
    movement_pattern_id
  )
  where coefficient > 0;

insert into public.exercise_movement_pattern_coefficients (
  mapping_version_id,
  exercise_id,
  movement_pattern_id,
  coefficient,
  rationale_status,
  rationale
)
select
  version.id,
  exercise.id,
  pattern.id,
  coefficient.value::text::numeric(4, 3),
  'methodology_only',
  case
    when coefficient.value::text::numeric = 0 then
      'The source matrix marks this pattern absent or too trivial to model for this exercise. An exercise-specific review note has not yet been documented.'
    else
      format(
        'The source matrix assigns an independent biomechanical contribution coefficient of %s. An exercise-specific justification has not yet been documented.',
        coefficient.value::text
      )
  end
from movement_matrix_import source
cross join jsonb_array_elements(source.payload -> 'exercises') exercise_source
cross join lateral jsonb_array_elements(exercise_source -> 'coefficients')
  with ordinality coefficient(value, source_order)
join public.exercises exercise
  on exercise.name = exercise_source ->> 'name'
join public.movement_patterns pattern
  on pattern.source_order = coefficient.source_order
join public.movement_mapping_versions version
  on version.code = 'initial_2026_08_07';

do $$
declare
  version_id bigint := (
    select id
    from public.movement_mapping_versions
    where code = 'initial_2026_08_07'
  );
begin
  if (select count(*) from public.exercises) <> 140 then
    raise exception 'Global exercise catalogue count mismatch';
  end if;

  if (select count(*) from public.exercise_aliases) <> 140 then
    raise exception 'Exercise alias count mismatch';
  end if;

  if (select count(*) from public.movement_patterns) <> 40 then
    raise exception 'Movement pattern count mismatch';
  end if;

  if (
    select count(*)
    from public.exercise_movement_pattern_coefficients
    where mapping_version_id = version_id
  ) <> 5600 then
    raise exception 'Movement matrix cell count mismatch';
  end if;

  if (
    select count(*)
    from public.exercise_movement_pattern_coefficients
    where mapping_version_id = version_id
      and coefficient > 0
  ) <> 556 then
    raise exception 'Non-zero movement matrix cell count mismatch';
  end if;

  if exists (
    select 1
    from public.session_exercises se
    left join public.exercises e on e.id = se.exercise_id
    where e.id is null
  ) then
    raise exception 'A performed exercise lost its global exercise link';
  end if;
end
$$;

alter table public.exercise_aliases enable row level security;
alter table public.movement_patterns enable row level security;
alter table public.movement_mapping_versions enable row level security;
alter table public.exercise_movement_pattern_coefficients enable row level security;

create policy "Authenticated users can view global exercises"
  on public.exercises for select to authenticated
  using (true);
create policy "Authenticated users can view exercise aliases"
  on public.exercise_aliases for select to authenticated
  using (true);
create policy "Authenticated users can view movement patterns"
  on public.movement_patterns for select to authenticated
  using (true);
create policy "Authenticated users can view mapping versions"
  on public.movement_mapping_versions for select to authenticated
  using (true);
create policy "Authenticated users can view movement coefficients"
  on public.exercise_movement_pattern_coefficients for select to authenticated
  using (true);

revoke all on public.exercises,
              public.exercise_aliases,
              public.movement_patterns,
              public.movement_mapping_versions,
              public.exercise_movement_pattern_coefficients
  from anon, authenticated;

grant select on public.exercises,
                public.exercise_aliases,
                public.movement_patterns,
                public.movement_mapping_versions,
                public.exercise_movement_pattern_coefficients
  to authenticated;

revoke all on sequence public.exercises_id_seq,
                       public.exercise_aliases_id_seq,
                       public.movement_patterns_id_seq,
                       public.movement_mapping_versions_id_seq
  from anon, authenticated;

comment on table public.exercises is
  'Global, app-managed exercise catalogue shared by every user. Equipment remains attached to performed exercises.';
comment on column public.exercises.code is
  'Stable machine identifier. It does not change when the display name changes.';
comment on column public.session_exercises.exercise is
  'Historical exercise-name snapshot retained exactly as recorded.';
comment on column public.session_exercises.exercise_id is
  'Reference to the global exercise catalogue; it is not user-owned reference data.';
comment on table public.exercise_aliases is
  'Global import aliases used to resolve historical labels to canonical exercises.';
comment on table public.movement_patterns is
  'Global biomechanical dimensions parsed from the movement-pattern matrix columns.';
comment on table public.movement_mapping_versions is
  'Immutable publication metadata for complete exercise-by-movement-pattern matrices.';
comment on table public.exercise_movement_pattern_coefficients is
  'One explicit cell per exercise, movement pattern, and matrix version, including zero values.';
comment on column public.exercise_movement_pattern_coefficients.coefficient is
  'Independent 0-to-1 biomechanical contribution coefficient; not a percentage or row-normalized share.';
comment on column public.exercise_movement_pattern_coefficients.rationale_status is
  'methodology_only means the general coefficient methodology exists but exercise-specific justification remains outstanding.';

commit;
